Brake.kernel_code:
pub struct Brake {
    pub last_setting: i32,
    pub last_update_ms: u64,
    pub on: bool,
}

lamps.kernel_code:
pub fn lamps(phase: bool, pattern: Blink) -> Lamps {
    if !phase {
        return Lamps { left: false, right: false };
    }
    match pattern {
        Blink::Left => Lamps { left: true, right: false },
        Blink::Right => Lamps { left: false, right: true },
        Blink::Off => Lamps { left: false, right: false },
        Blink::Alarm => Lamps { left: true, right: true },
    }
}

lamps.lean:
def lamps (phase : Bool) (pattern : Blink) : Result Lamps := do
  if phase
  then
    match pattern with
    | Blink.Left => ok { left := true, right := false }
    | Blink.Right => ok { left := false, right := true }
    | Blink.Off => ok { left := false, right := false }
    | Blink.Alarm => ok { left := true, right := true }
  else ok { left := false, right := false }

brake_on_motor.kernel_code:
pub fn brake_on_motor(s: Brake, value: i32, now_ms: u64) -> Brake {
    let braking = magnitude(value) < magnitude(s.last_setting);
    Brake { last_setting: value, last_update_ms: now_ms, on: braking }
}

Blinker.kernel_code:
pub struct Blinker {
    pub pattern: Blink,
    pub phase: bool,
}

clamp.kernel_code:
pub fn clamp(value: i32, limit: i32) -> i32 {
    if value < -limit {
        -limit
    } else if value > limit {
        limit
    } else {
        value
    }
}

magnitude.kernel_code:
pub fn magnitude(v: i32) -> u32 {
    if v < 0 {
        // -(v + 1) + 1, so i32::MIN maps to 2^31
        ((-(v + 1)) as u32) + 1
    } else {
        v as u32
    }
}

Lamps.kernel_code:
pub struct Lamps {
    pub left: bool,
    pub right: bool,
}

motor_percentage.kernel_code:
pub fn motor_percentage(value: i32) -> u8 {
    (clamp(value, MOTOR_LIMIT) + 50) as u8
}

blinker_tick.kernel_code:
pub fn blinker_tick(s: Blinker) -> (Blinker, Lamps) {
    let phase = !s.phase;
    (Blinker { pattern: s.pattern, phase }, lamps(phase, s.pattern))
}

servo_duty.kernel_code:
pub fn servo_duty(percentage: u8, min_us: u32, max_us: u32, duty_space: u32, cycle_us: u32) -> u32 {
    let p = if percentage > 100 { 100 } else { percentage as u32 };
    let range = max_us - min_us;
    let abs_duty = min_us + range * p / 100;
    abs_duty * duty_space / cycle_us
}

brake_on_tick.kernel_code:
pub fn brake_on_tick(s: Brake, now_ms: u64) -> (Brake, bool) {
    if s.on && now_ms > s.last_update_ms && now_ms - s.last_update_ms > BRAKELIGHT_TIMEOUT_MS {
        (Brake { last_setting: s.last_setting, last_update_ms: s.last_update_ms, on: false }, true)
    } else {
        (s, false)
    }
}

blinker_command.kernel_code:
pub fn blinker_command(s: Blinker, cmd: Blink) -> (Blinker, Option<Lamps>) {
    match s.pattern {
        Blink::Off => match cmd {
            Blink::Off => (s, Some(Lamps { left: false, right: false })),
            _ => (Blinker { pattern: cmd, phase: s.phase }, None),
        },
        _ => {
            let l = lamps(true, cmd);
            (Blinker { pattern: cmd, phase: true }, Some(l))
        }
    }
}

